/* ─── Navigation: breadcrumb, pager, steps, top bar ─── */
.crumbs { min-width: 0; display: flex; flex-wrap: wrap; gap: var(--s2); font-size: var(--text-sm); color: var(--muted); }
.crumbs li + li::before { content: "/"; margin-inline-end: var(--s2); color: var(--ink-3); }
.crumbs [aria-current="page"] { color: var(--foreground); }
.pager { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); font-size: var(--text-sm); }
.pager a, .pager button { min-width: 36px; padding: var(--s2) var(--s3); text-align: center; border: 1px solid var(--rule); text-decoration: none; }
.pager a:hover, .pager button:hover:not(:disabled) { border-color: var(--foreground); }
.pager [aria-current="page"] { background: var(--foreground); color: var(--background); border-color: var(--foreground); }
.pager button:disabled { opacity: 0.5; cursor: not-allowed; }
.steps { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: var(--s3); counter-reset: step; }
.step { counter-increment: step; padding-top: var(--s3); border-top: 2px solid var(--rule); font-size: var(--text-sm); color: var(--muted); }
.step::before { content: counter(step, decimal-leading-zero); display: block; font-size: var(--text-xs); }
.step[data-state="done"] { border-top-color: var(--foreground); color: var(--foreground); }
.step[aria-current="step"] { border-top-color: var(--accent); color: var(--foreground); font-weight: 500; }
.topbar { display: flex; align-items: center; gap: var(--s5); padding: var(--s4) var(--s5); border-bottom: 1px solid var(--rule); flex-wrap: wrap; }
.topbar .brand { padding: 0; }
.topbar-nav { display: flex; flex-wrap: wrap; gap: var(--s5); margin-inline-end: auto; font-size: var(--text-sm); }
.topbar-nav a { text-decoration: none; color: var(--muted); }
.topbar-nav a:hover, .topbar-nav a[aria-current="page"] { color: var(--foreground); }
.tab[aria-selected="true"] { color: var(--foreground); box-shadow: inset 0 2px 0 var(--foreground); }
.tabpanel { padding-top: var(--s5); }
.tabpanel[hidden] { display: none; }
[dir="rtl"] .crumbs li + li::before { display: inline-block; transform: scaleX(-1); }

source.content:
'use client';
import {forwardRef, useState, type HTMLAttributes} from 'react';

export interface PaginationProps extends Omit<HTMLAttributes<HTMLElement>, 'onChange'> {
  /** Current page, 1-based, when controlled. Pair with `onPageChange`. */
  page?: number;
  /** The starting page when uncontrolled. Default 1. */
  defaultPage?: number;
  /** Total number of pages. */
  pageCount: number;
  /** Called with the new 1-based page number when the user picks a page or presses Prev or Next. */
  onPageChange?: (page: number) => void;
  /** How many numbers to show on each side of the current page. */
  siblings?: number;
}

/** Page numbers with the first and last always visible and "…" for gaps. Pure function exported for testing. */
export function pageWindow(page: number, count: number, siblings = 1): Array<number | 'gap'> {
  const out: Array<number | 'gap'> = [];
  const left = Math.max(2, page - siblings), right = Math.min(count - 1, page + siblings);
  out.push(1);
  if (left > 2) out.push('gap');
  for (let p = left; p <= right; p++) out.push(p);
  if (right < count - 1) out.push('gap');
  if (count > 1) out.push(count);
  return out;
}

/** Previous, numbered pages and next, as buttons. The current page has aria-current. */
export const Pagination = forwardRef<HTMLElement, PaginationProps>(function Pagination({page: pageProp, defaultPage = 1, pageCount, onPageChange, siblings = 1, ...rest}, ref) {
  const [inner, setInner] = useState(defaultPage);
  const page = pageProp ?? inner;
  const go = (p: number) => {
    const next = Math.min(pageCount, Math.max(1, p));
    if (pageProp === undefined) setInner(next);
    onPageChange?.(next);
  };
  return (
    <nav ref={ref} aria-label="Pagination" {...rest}>
      <div className="pager">
        <button type="button" disabled={page <= 1} onClick={() => go(page - 1)}>Prev</button>
        {pageWindow(page, pageCount, siblings).map((p, i) =>
          p === 'gap' ? <span key={`g${i}`} className="muted" aria-hidden="true">…</span> : (
            <button key={p} type="button" aria-current={p === page ? 'page' : undefined} aria-label={`Page ${p}`} onClick={() => go(p)}>{p}</button>
          ))}
        <button type="button" disabled={page >= pageCount} onClick={() => go(page + 1)}>Next</button>
      </div>
    </nav>
  );
});
